DECLARE
  i NUMBER := 1; s NUMBER := 0;
BEGIN
  LOOP
    s := s + i;
    i := i + 1;
    EXIT WHEN i > 10;
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('Sum: ' || s);
END;

