DECLARE
  n NUMBER := 5; f NUMBER := 1;
BEGIN
  WHILE n > 0 LOOP
    f := f * n;
    n := n - 1;
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('Factorial: ' || f);
END;

DECLARE
  n NUMBER := 123; s NUMBER := 0;
BEGIN
  WHILE n > 0 LOOP
    s := s + MOD(n, 10);
    n := TRUNC(n / 10);
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('Sum of digits: ' || s);
END;

DECLARE
  n NUMBER := 123; r NUMBER := 0;
BEGIN
  WHILE n > 0 LOOP
    r := (r * 10) + MOD(n, 10);
    n := TRUNC(n / 10);
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('Reversed: ' || r);
END;

DECLARE
  n NUMBER := 121; temp NUMBER; r NUMBER := 0;
BEGIN
  temp := n;
  WHILE n > 0 LOOP
    r := (r * 10) + MOD(n, 10);
    n := TRUNC(n / 10);
  END LOOP;
  IF temp = r THEN DBMS_OUTPUT.PUT_LINE('Palindrome'); ELSE DBMS_OUTPUT.PUT_LINE('Not'); END IF;
END;

DECLARE
  a NUMBER := 0; b NUMBER := 1; c NUMBER; i NUMBER := 1;
BEGIN
  DBMS_OUTPUT.PUT_LINE(a);
  DBMS_OUTPUT.PUT_LINE(b);
  WHILE i <= 3 LOOP
    c := a + b; a := b; b := c;
    DBMS_OUTPUT.PUT_LINE(c);
    i := i + 1;
  END LOOP;
END;

