DECLARE
  j NUMBER; is_prime BOOLEAN;
BEGIN
  FOR i IN 2..50 LOOP
    is_prime := TRUE;
    FOR j IN 2..TRUNC(i/2) LOOP
      IF MOD(i, j) = 0 THEN is_prime := FALSE; EXIT; END IF;
    END LOOP;
    IF is_prime THEN DBMS_OUTPUT.PUT(i || ' '); END IF;
  END LOOP;
  DBMS_OUTPUT.NEW_LINE;
END;

