DECLARE
  se NUMBER := 0; so NUMBER := 0;
BEGIN
  FOR i IN 1..10 LOOP
    IF MOD(i, 2) = 0 THEN se := se + i; ELSE so := so + i; END IF;
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('Even Sum: ' || se || ', Odd Sum: ' || so);
END;
